using Bogmem.Harness;
if(args.Length==0||args[0] is "--help" or "-h"){Console.WriteLine("bogmem - parity harness\n\nCommands:\n  parity [module] [--report path]\n  --help");return 0;}
if(args[0]=="parity"){var module=args.Length>1&&!args[1].StartsWith('-')?args[1]:"config";var report=args.Skip(1).SkipWhile(x=>x!="--report").Skip(1).FirstOrDefault()??"parity_report.json";var file=CorpusReplay.FindModule(Directory.GetCurrentDirectory(),module);if(!File.Exists(file)){Console.Error.WriteLine($"No frozen corpus for module '{module}'.");return 2;}var count=CorpusReplay.Read(file).Count();ParityReportWriter.Write(report,module,[new("corpus_loaded","EXACT",true,$"{count} frozen vectors loaded")]);Console.WriteLine($"parity {module}: loaded {count} frozen vectors; report={report}");return 0;}
Console.Error.WriteLine($"Unknown command '{args[0]}'. Use --help.");return 2;
